package com.example.starter.rosconfig.model;

/**
 * ROS 参数支持的标量类型。
 */
public enum ParamType {
    /** 字符串 */
    STRING,
    /** 64 位整数 */
    INTEGER,
    /** 双精度浮点数 */
    DOUBLE,
    /** 布尔值 */
    BOOLEAN;

    /**
     * 将 JSON 反序列化得到的对象转换为该类型的规范值，类型不兼容时抛出 {@link IllegalArgumentException}。
     */
    public Object coerce(Object raw) {
        // TODO 骨架：在 SchemaValidator 落地前保持空实现
        throw new UnsupportedOperationException("coerce not implemented");
    }
}

package com.example.starter.rosconfig.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.util.Map;

/**
 * 热更新事务中针对单个节点的变更集。
 *
 * @param node            目标节点名
 * @param expectedVersion 调用方持有的节点配置单调版本，服务端版本不一致时拒绝整笔事务
 * @param params          待变更参数名到新值的映射；不允许出现静态参数
 */
public record ChangeSetRequest(
        @NotBlank String node,
        @NotNull Long expectedVersion,
        @NotNull Map<String, Object> params
) {
}

package com.example.starter.rosconfig.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;

import java.util.List;

/**
 * 跨节点事务式热更新请求。
 *
 * @param transactionId 调用方生成的幂等键；同键同参返回原结果，同键异参返回 409
 * @param changes       各节点变更集，至少包含一个节点
 */
public record TransactionRequest(
        @NotBlank String transactionId,
        @NotEmpty List<@Valid ChangeSetRequest> changes
) {
}

