package com.example.starter.rosconfig.dto;

/**
 * 事务中单个节点的处理结果状态。
 */
public enum NodeResultStatus {
    /** 节点已接受候选配置并完成应用 */
    ACCEPTED,
    /** Schema/类型/必填/依赖等本地校验失败，未触达节点 */
    SCHEMA_REJECTED,
    /** 调用方 expectedVersion 与服务端当前单调版本不一致 */
    VERSION_CONFLICT,
    /** 变更集中包含静态参数 */
    STATIC_PARAM,
    /** 节点主动拒绝候选配置 */
    REJECTED,
    /** 节点在配置时限内无响应 */
    TIMEOUT
}

package com.example.starter.rosconfig.dto;

/**
 * 单个节点在事务中的处理结果。
 *
 * @param node       节点名
 * @param status     结果状态
 * @param message    拒绝/失败原因，成功时为 null
 * @param oldVersion 事务前节点版本
 * @param newVersion 提交成功后的节点版本，未提交时为 null
 */
public record NodeResult(
        String node,
        NodeResultStatus status,
        String message,
        Long oldVersion,
        Long newVersion
) {
    public static NodeResult of(String node, NodeResultStatus status, String message, Long oldVersion, Long newVersion) {
        return new NodeResult(node, status, message, oldVersion, newVersion);
    }
}

package com.example.starter.rosconfig.dto;

import java.util.List;
import java.util.Map;

/**
 * 热更新事务的响应体；提交失败时 committed=false，数据库值、节点应用值均保持原状。
 *
 * @param transactionId 幂等事务键
 * @param committed     是否原子提交成功
 * @param eventCursor   提交成功后写入的唯一事务事件游标；重复事务返回首次结果；未提交为 null
 * @param versions      提交成功后各节点的新版本
 * @param results       各节点的逐项结果
 */
public record TransactionResponse(
        String transactionId,
        boolean committed,
        Long eventCursor,
        Map<String, Long> versions,
        List<NodeResult> results
) {
}

package com.example.starter.rosconfig.dto;

import java.util.Map;

/**
 * 节点配置视图：默认值与已提交值合并后的完整参数快照。
 *
 * @param node       节点名
 * @param version    当前单调版本
 * @param group      参数组（按 Schema 归属）
 * @param params     参数名到当前有效值的映射
 * @param dynamic    参数名到是否可热更新的映射
 * @param pendingRestart 有待重启生效的静态参数名
 */
public record ConfigView(
        String node,
        long version,
        String group,
        Map<String, Object> params,
        Map<String, Boolean> dynamic,
        java.util.List<String> pendingRestart
) {
}

