/** 幂等事务记录（首次处理结果，失败/成功都留存以便同参重放）。 */
public record TransactionRecord(String transactionId, String requestHash,
                                boolean committed, String responseText) {
}

/**
 * 尝试插入事务记录以抢占幂等键；插入成功返回 true，键已存在返回 false。
 */
public boolean tryInsertRecord(String transactionId, String requestHash,
                               boolean committed, String responseJson, long createdAt) {
    try {
        jdbc.update("INSERT INTO transaction_record(transaction_id, request_hash, committed, response_text, created_at) "
                        + "VALUES (?, ?, ?, ?, ?)",
                transactionId, requestHash, committed, responseJson, createdAt);
        return true;
    } catch (DuplicateKeyException e) {
        return false;
    }
}

/** 读取已有事务记录；不存在返回 null。 */
public TransactionRecord findRecord(String transactionId) {
    return jdbc.query("SELECT transaction_id, request_hash, committed, response_text "
                    + "FROM transaction_record WHERE transaction_id = ?",
            rs -> rs.next()
                    ? new TransactionRecord(rs.getString(1), rs.getString(2),
                        rs.getBoolean(3), rs.getString(4))
                    : null, transactionId);
}

