                String message = "static parameters cannot be hot-updated: "
                        + String.join(", ", staticParams)
                        + "; use pending restart config instead";
                results.add(NodeResult.of(node, NodeResultStatus.STATIC_PARAM, message, null, null));
                localFailure = true;
                continue;
            }

