            if (change.expectedVersion() != currentVersion) {
                results.add(NodeResult.of(node, NodeResultStatus.VERSION_CONFLICT,
                        "expected version " + change.expectedVersion()
                                + " but current is " + currentVersion,
                        currentVersion, null));
                localFailure = true;
                continue;
            }
