                        List<NodeResult> committedResults = new ArrayList<>();
                        for (Map.Entry<String, Long> entry : expectedVersions.entrySet()) {
                            committedResults.add(NodeResult.of(entry.getKey(),
                                    NodeResultStatus.ACCEPTED, null,
