        if (!commitService.claim(transactionId, requestHash, now)) {
            EventRepository.TransactionRecord raced = eventRepository.findRecord(transactionId);
            if (raced != null && raced.requestHash().equals(requestHash)
                    && !EventRepository.STATUS_PROCESSING.equals(raced.status())) {
                return parseResponse(raced.responseText());
